package net.civeira.phylax.feature.observe.observedissue.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFail;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssue;
import net.civeira.phylax.feature.observe.observedissue.domain.valueobject.CountVO;

@RequiredArgsConstructor
public class CountValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<CountVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @param count
   * @return
   */
  public T count(CountVO count) {
    this.value = Optional.of(count);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param count
   * @return
   */
  public T count(Optional<CountVO> count) {
    this.value = count;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param count
   * @return
   */
  public T count(Integer count) {
    this.value = Optional.of(CountVO.from(count));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<Integer> getCount() {
    return value.map(CountVO::getCount);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<CountVO> getCountValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public CountVO readCount(final Optional<ObservedIssue> original, final ConstraintFailList fails) {
    CountVO result = value.orElse(original.map(ObservedIssue::getCountValue).orElse(null));
    if (null == result) {
      fails.add(new ConstraintFail("REQUIRED", "count", null));
    }
    return result;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetCount() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetCountIfMatches(final String field) {
    if ("count".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
